// =========================================================
// KYDNO KORE - 5 REEL 3D COIN ANIMATION
// Clean circular coin version
// =========================================================

const KYDNO_COIN_ASSETS = {
    heads: "assets/kydno_kore_heads_coin.png",
        tails: "assets/kydno_kore_tails_coin.png"
        };

        function getRandomKydnoSide() {
                return Math.random() < 0.5
                        ? "heads"
                                : "tails";
                                }
        
     // =========================================================
     // KYDNO KORE - VERTICAL COIN REEL
     // =========================================================
     
     function createKydnoCoin(side) {
     
         const coin = document.createElement("img");
         
             coin.className = "kydno-reel-coin";
             
                 coin.src = KYDNO_COIN_ASSETS[side];
                 
                     coin.alt =
                             side === "heads"
                                         ? "Kydno Kore Heads Coin"
                                                     : "Kydno Kore Tails Coin";
                                                     
                                                         coin.dataset.side = side;
                                                         
                                                             return coin;
                                                             }
                                                             
                                                             
                                                                                                                     
                                                             // =========================================================
                                                             // CREATE ONE VERTICAL REEL
                                                             // =========================================================

                                                             function createKydnoVerticalReel(reelElement) {

                                                                 if (!reelElement) return;

                                                                     reelElement.innerHTML = "";

                                                                         const track =
                                                                                 document.createElement("div");

                                                                                     track.className =
                                                                                             "kydno-vertical-track";


                                                                                                 // Lots of coins so the reel can continuously
                                                                                                     // travel downward without running out.

                                                                                                         // Create one completely random sequence for this reel
                                                                                                         const reelCoins = [];

                                                                                                         for (let i = 0; i < 50; i++) {

                                                                                                             const side = getRandomKydnoSide();

                                                                                                                 const coin =
                                                                                                                         createKydnoCoin(side);

                                                                                                                             reelCoins.push(coin);

                                                                                                                                 track.appendChild(coin);
                                                                                                                                 }

                                                                                                                                 // Duplicate THIS reel's own random sequence.
                                                                                                                                 // This creates a seamless loop without synchronizing
                                                                                                                                 // the other four reels.
                                                                                                                                 reelCoins.forEach((coin) => {

                                                                                                                                     const duplicate =
                                                                                                                                             coin.cloneNode(true);

                                                                                                                                                 track.appendChild(duplicate);
                                                                                                                                                 });
                                                                                                         


                                                                                                                                                                                             reelElement.appendChild(track);


                                                                                                                                                                                                 // Large final result coin.

                                                                                                                                                                                                     const landedCoin =
                                                                                                                                                                                                             document.createElement("img");

                                                                                                                                                                                                                 landedCoin.className =
                                                                                                                                                                                                                         "kydno-landed-coin";

                                                                                                                                                                                                                             landedCoin.alt = "";

                                                                                                                                                                                                                                 reelElement.appendChild(
                                                                                                                                                                                                                                         landedCoin
                                                                                                                                                                                                                                             );
                                                                                                                                                                                                                                             }
                                                                                                                                                                                                     
                                                                                                                                                                                                     
                                                                                                                                                                                                     // =========================================================
                                                                                                                                                                                                     // BUILD ALL FIVE REELS
                                                                                                                                                                                                     // =========================================================
                                                                                                                                                                                                     
                                                                                                                                                                                                     const kydnoReelTracks = [];
                                                                                                                                                                                                     
                                                                                                                                                                                                     for (let i = 1; i <= 5; i++) {
                                                                                                                                                                                                     
                                                                                                                                                                                                         const reelElement =
                                                                                                                                                                                                                 document.getElementById(
                                                                                                                                                                                                                             `kydno-reel-${i}`
                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                         createKydnoVerticalReel(
                                                                                                                                                                                                                                                 reelElement
                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                         const track =
                                                                                                                                                                                                                                                                 reelElement?.querySelector(
                                                                                                                                                                                                                                                                             ".kydno-vertical-track"
                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                         if (track) {
                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                 kydnoReelTracks.push(
                                                                                                                                                                                                                                                                                                             track
                                                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                         // =========================================================
                                                                                                                                                                                                                                                                                                                         // SHOW LANDED COIN
                                                                                                                                                                                                                                                                                                                         // =========================================================
                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                         function showKydnoLandedCoin(
                                                                                                                                                                                                                                                                                                                             reelElement,
                                                                                                                                                                                                                                                                                                                                 side
                                                                                                                                                                                                                                                                                                                                 ) {
                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                     if (!reelElement) return;
                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                         const landedCoin =
                                                                                                                                                                                                                                                                                                                                                 reelElement.querySelector(
                                                                                                                                                                                                                                                                                                                                                             ".kydno-landed-coin"
                                                                                                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                         if (!landedCoin) return;
                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                             landedCoin.src =
                                                                                                                                                                                                                                                                                                                                                                                     KYDNO_COIN_ASSETS[side];
                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                         landedCoin.classList.add(
                                                                                                                                                                                                                                                                                                                                                                                                 "show"
                                                                                                                                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                                                                                                                                     }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
    // =========================================================
    // KYDNO KORE - 5 REEL SPIN TEST
    // =========================================================

    const KYDNO_TEST_RESULTS = [
        "heads",
            "tails",
                "heads",
                    "tails",
                        "heads"
                        ];                                 
  // =========================================================
  // RUN THE 5 REEL SPIN TEST
  // =========================================================
   function spinKydnoReel(
        track,
            reelElement,
                resultSide,
                    reelNumber,
                        duration
                        ) {

                            if (!track || !reelElement) return;

                                const coins =
                                        Array.from(
                                                    track.querySelectorAll(".kydno-reel-coin")
                                                            );

                                                                if (coins.length < 8) return;

                                                                    const coinHeight =
                                                                            coins[0].getBoundingClientRect().height;

                                                                                const firstCoin = coins[0];
                                                                                    const secondCoin = coins[1];

                                                                                        const step =
                                                                                                secondCoin.offsetTop -
                                                                                                        firstCoin.offsetTop;

                                                                                                            if (!step) return;

                                                                                                                const reelHeight =
                                                                                                                        reelElement.clientHeight;

                                                                                                                            let currentY =
                                                                                                                                    (reelHeight / 2) -
                                                                                                                                            (2 * step) -
                                                                                                                                                    (coinHeight / 2);

                                                                                                                                                        track.style.transition = "none";

                                                                                                                                                            track.style.transform =
                                                                                                                                                                    `translate(-50%, ${currentY}px)`;

                                                                                                                                                                        /*
                                                                                                                                                                                VERY FAST CONTINUOUS SPIN

                                                                                                                                                                                        The entire duplicated 100-coin strip
                                                                                                                                                                                                stays in place.

                                                                                                                                                                                                        We do NOT move coins between the
                                                                                                                                                                                                                beginning and end of the DOM.
                                                                                                                                                                                                                    */

                                                                                                                                                                                                                        const speed =
                                                                                                                                                                                                                                reelNumber === 5
                                                                                                                                                                                                                                            ? 18
                                                                                                                                                                                                                                                        : 22;

                                                                                                                                                                                                                                                            let running = true;

                                                                                                                                                                                                                                                                const startTime =
                                                                                                                                                                                                                                                                        performance.now();

                                                                                                                                                                                                                                                                            /*
                                                                                                                                                                                                                                                                                    Exactly one 50-coin sequence.
                                                                                                                                                                                                                                                                                            The second 50 coins are its duplicate.
                                                                                                                                                                                                                                                                                                */

                                                                                                                                                                                                                                                                                                    const cycleHeight =
                                                                                                                                                                                                                                                                                                            step * 50;

                                                                                                                                                                                                                                                                                                                function continuousSpin(currentTime) {

                                                                                                                                                                                                                                                                                                                        if (!running) return;

                                                                                                                                                                                                                                                                                                                                currentY += speed;

                                                                                                                                                                                                                                                                                                                                        /*
                                                                                                                                                                                                                                                                                                                                                    Seamless loop.

                                                                                                                                                                                                                                                                                                                                                                We move the visual position back by
                                                                                                                                                                                                                                                                                                                                                                            exactly one complete 50-coin cycle.
                                                                                                                                                                                                                                                                                                                                                                                    */

                                                                                                                                                                                                                                                                                                                                                                                            if (currentY > cycleHeight) {
                                                                                                                                                                                                                                                                                                                                                                                                        currentY -= cycleHeight;
                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                        track.style.transform =
                                                                                                                                                                                                                                                                                                                                                                                                                                    `translate(-50%, ${currentY}px)`;

                                                                                                                                                                                                                                                                                                                                                                                                                                            const elapsed =
                                                                                                                                                                                                                                                                                                                                                                                                                                                        currentTime - startTime;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (elapsed >= duration) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            running = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        landKydnoReel(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        track,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        reelElement,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        resultSide,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        reelNumber
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                requestAnimationFrame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            continuousSpin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            requestAnimationFrame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    continuousSpin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // =========================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // AGGRESSIVE SLOT REEL LANDING
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // =========================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function landKydnoReel(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      track,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          reelElement,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              resultSide,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  reelNumber
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!track || !reelElement) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const landedCoin =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  reelElement.querySelector(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ".kydno-landed-coin"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!landedCoin) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              landedCoin.src =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      KYDNO_COIN_ASSETS[resultSide];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          landedCoin.classList.remove("show");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              reelElement.classList.remove(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "kydno-reel-snap"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              reelElement.classList.remove(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "kydno-reel-five-pull"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              void reelElement.offsetWidth;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const snapClass =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          reelNumber === 5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ? "kydno-reel-five-pull"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : "kydno-reel-snap";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const snapDuration =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              reelNumber === 5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ? 720
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      : 420;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          reelElement.classList.add(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  snapClass
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Keep the moving coins visible
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          during the entire snap.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  setTimeout(() => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      The snap is finished.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  NOW hide the moving coins.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  track
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              .querySelectorAll(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ".kydno-reel-coin"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .forEach((coin) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      coin.style.opacity = "0";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      NOW show the oversized result coin.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      landedCoin.classList.add("show");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              reelElement.classList.remove(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          snapClass
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }, snapDuration);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

  function runKydnoSpinTest() {

      // Reset the reels first
         kydnoReelTracks.forEach((track) => {

                track.style.transition = "none";

                    track.style.transform =
                            "translate(-50%, 0px)";

                                track
                                        .querySelectorAll(".kydno-reel-coin")
                                                .forEach((coin) => {
                                                            coin.style.opacity = "1";
                                                                    });
                                                                    });
         

                                                                              // Hide previous result coins
                                                                                  kydnoReelTracks.forEach((track, index) => {

                                                                                          const reelElement =
                                                                                                      document.getElementById(
                                                                                                                      `kydno-reel-${index + 1}`
                                                                                                                                  );

                                                                                                                                          const landedCoin =
                                                                                                                                                      reelElement?.querySelector(
                                                                                                                                                                      ".kydno-landed-coin"
                                                                                                                                                                                  );

                                                                                                                                                                                          if (landedCoin) {
                                                                                                                                                                                                      landedCoin.classList.remove("show");
                                                                                                                                                                                                                  landedCoin.removeAttribute("src");
                                                                                                                                                                                                                          }
                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                  // Wait for the reset to happen
                                                                                                                                                                                                                                      requestAnimationFrame(() => {

                                                                                                                                                                                                                                              requestAnimationFrame(() => {

                                                                                                                                                                                                                                                          // Reel 1 → 2 → 3 → 4
                                                                                                                                                                                                                                                                      // Reel 5 gets the dramatic slowdown

                                                                                                                                                                                                                                                                                  const durations = [
                                                                                                                                                                                                                                                                                        1300,
                                                                                                                                                                                                                                                                                            1700,
                                                                                                                                                                                                                                                                                                2100,
                                                                                                                                                                                                                                                                                                    2500,
                                                                                                                                                                                                                                                                                                        4000
                                                                                                                                                                                                                                                                                                        ];
                                                                                                                                                                                                                                                                                  

                                                                                                                                                                                                                                                                                                                                                                                          kydnoReelTracks.forEach(
                                                                                                                                                                                                                                                                                                                                                                                                          (track, index) => {

                                                                                                                                                                                                                                                                                                                                                                                                                              const reelNumber =
                                                                                                                                                                                                                                                                                                                                                                                                                                                      index + 1;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const reelElement =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.getElementById(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              `kydno-reel-${reelNumber}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          spinKydnoReel(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  track,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          reelElement,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  KYDNO_TEST_RESULTS[index],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          reelNumber,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  durations[index]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Automatically start the test
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setTimeout(() => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  runKydnoSpinTest();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }, 500);


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Allows us to restart the test later
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  window.runKydnoSpinTest =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      runKydnoSpinTest;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
